<?php session_start(); require_once '../includes/funcoes.php'; if(!isset($_SESSION['usuario_id'])){header('Location: ../login.php');exit;} $a='../data/colaboradores/terceiros.json';$l=lerArquivoJSON($a);if(!is_array($l))$l=[];$id=$_GET['id']??$_POST['id']??'';$v=[];foreach($l as $t){if(($t['id']??'')===$id)$v=$t;}if($_SERVER['REQUEST_METHOD']==='POST'){$n=['id'=>$id?:uniqid('terceiro_'),'nome'=>trim($_POST['nome']??''),'cpf'=>preg_replace('/\D/','',$_POST['cpf']??''),'cargo'=>trim($_POST['cargo']??''),'email'=>trim($_POST['email']??''),'bit_instalado'=>($_POST['bit_instalado']??'nao')==='sim'?'sim':'nao'];$ok=false;foreach($l as $i=>$t){if(($t['id']??'')===$n['id']){$l[$i]=$n;$ok=true;}}if(!$ok)$l[]=$n;salvarArquivoJSON($a,$l);header('Location: index.php');exit;} ?><h1>Terceiro</h1><form method="post"><input type="hidden" name="id" value="<?=htmlspecialchars($v['id']??$id)?>">Nome <input name="nome" required value="<?=htmlspecialchars($v['nome']??'')?>"><br>CPF <input name="cpf" required value="<?=htmlspecialchars($v['cpf']??'')?>"><br>Cargo <input name="cargo" value="<?=htmlspecialchars($v['cargo']??'')?>"><br>E-mail <input name="email" value="<?=htmlspecialchars($v['email']??'')?>"><br>Bit instalado <select name="bit_instalado"><option value="nao">Não</option><option value="sim">Sim</option></select><br><button>Salvar</button></form>